<script setup lang="ts">
import { errorMessage } from '~/utils/format'
const open = defineModel<boolean>('open', { default: false })
const props = defineProps<{ recordId: string }>()
interface History { id: string; at: string; action: string; before: string; after: string }
const rows = ref<History[]>([]), error = ref(''), loading = ref(false)
const labels: Record<string, string> = { name: '名称', state: '状态', purposes: '用途', contact: '联系人', phone: '电话', startDate: '开始日期', endDate: '结束日期', notes: '备注', floor: '楼层', area: '面积', business: '经营内容', owner: '房东', ownerPhone: '房东电话', tenantCount: '居住人数', storedGoods: '存放物品', inspector: '检查人员', from: '开始日期', to: '完成期限', archived: '停用', address: '地址', disabled: '停用', description: '问题', requirement: '整改要求', deadline: '整改期限', responsibleUnit: '责任单位', follower: '跟进人' }
function parse(text: string): Record<string, unknown> { try { const x = JSON.parse(text); return x.data ? { ...x.data, name: x.name, archived: x.archived } : x } catch { return {} } }
function display(value: unknown) { return typeof value === 'boolean' ? (value ? '是' : '否') : Array.isArray(value) ? value.join('、') : String(value ?? '') }
function changes(row: History) { const before = parse(row.before), after = parse(row.after); return Object.entries(labels).filter(([key]) => key in after && JSON.stringify(before[key]) !== JSON.stringify(after[key])).map(([key, label]) => ({ label, before: display(before[key]), after: display(after[key]) })) }
function photos(row: History): string[] { const value = parse(row.after).photoIds; return Array.isArray(value) ? value.filter(x => typeof x === 'string') : [] }
watch([open, () => props.recordId], async () => { if (!open.value || !props.recordId) return; loading.value = true; error.value = ''; rows.value = []; try { rows.value = await $fetch(`/api/history/${props.recordId}`) } catch (e) { error.value = errorMessage(e) } finally { loading.value = false } })
</script>
<template><USlideover v-model:open="open" title="变更记录" :ui="{content:'w-full max-w-[600px]'}"><template #body><div class="space-y-4"><UAlert v-if="error" :description="error" color="error" /><p v-if="loading">加载中…</p><article v-for="row in rows" :key="row.id" class="border-b border-default pb-4"><div class="flex justify-between gap-2"><strong>{{ row.action }}</strong><span class="text-xs text-muted">{{ new Date(row.at).toLocaleString('zh-CN') }}</span></div><dl class="mt-2 space-y-2 text-sm"><div v-for="change in changes(row)" :key="change.label"><dt class="text-muted">{{ change.label }}</dt><dd class="break-words"><span v-if="change.before" class="line-through text-muted mr-2">{{ change.before }}</span>{{ change.after || '已清空' }}</dd></div></dl><div v-if="photos(row).length" class="flex gap-2 mt-2 overflow-x-auto"><a v-for="id in photos(row)" :key="id" :href="`/photos/${id}`" target="_blank"><img :src="`/photos/${id}?size=thumb`" class="size-16 rounded object-cover" alt="历史照片" loading="lazy" /></a></div></article><EmptyState v-if="!loading && !rows.length && !error" title="暂无变更记录" /></div></template></USlideover></template>
